```verilog
module ldpc_encoder(
    input wire clk,
    input wire reset,
    input wire data_in,
    output wire data_out
);

reg [7:0] data_reg;
reg [3:0] parity_reg;

always @(posedge clk or posedge reset)
begin
    if (reset)
    begin
        data_reg <= 8'b00000000;
        parity_reg <= 4'b0000;
    end
    else
    begin
        data_reg <= data_in;
        parity_reg <= parity_calc(data_reg);
        data_out <= data_reg[7:4] | (parity_reg[3:0] << 4);
    end
end

function [4:0] parity_calc(data);
    parity_calc <= data[7:4] ^ data[3:0];
endfunction : parity_calc

endmodule : ldpc_encoder
```

