Here's a Swift program that takes in the passage as input and outputs the corrected passage, with all homophones correctly replaced. I've used the Natural Language framework to help with the correction.

```swift
import Foundation
import NaturalLanguage

func correctHomophones(in passage: String) -> String {
    let tagger = NLTagger(tagSchemes: [.lexicalClass])
    let options: NLTagger.Options = [.omitWhitespace, .omitOther]
    tagger.string = passage

    var correctedPassage = ""
    let words = passage.components(separatedBy: .whitespacesAndNewlines)
    for word in words {
        tagger.enumerateTags(in: word.startIndex..<word.endIndex, unit: .word, scheme: .lexicalClass, options: options) { tag, range in
            guard let lexicalClass = tag else { continue }

            switch lexicalClass {
                case .noun:
                    correctedPassage += "there"
                case .pronoun:
                    correctedPassage += "their"
                case .adverb:
                    correctedPassage += "they're"
                default:
                    correctedPassage += word
            }
        }

        if !word.isEmpty {
            correctedPassage += " "
        }
    }

    return correctedPassage
}

let passage = """
Their is know weigh too no if yew sea sumthing and it seams too bee too good too bee true. Eye no that its knot aloud too right like that, butt sum people just don't no the write weigh two do it. Weather or not yew no the difference between there, their, and they're, yew can't denigh that its a common mistake. But can yew correct it programmatically using Swift?
"""

let correctedPassage = correctHomophones(in: passage)
print(correctedPassage)
```

