```

Replace `https://your-wordpress-site.com` with the actual URL of your WordPress site.

3. Use the CORS middleware in your Next.js route:

In your Next.js route, you can use the `corsMiddleware` to handle the requests from your WordPress site. For example, if you have a route called `api/data`, you can use the `corsMiddleware` like this:

```javascript
import { useRouter } from 'next/router';
import { corsMiddleware } from '../pages/api/cors';

export default function Data() {
  const router = useRouter();

  return (
    <div>
      <h1>Data</h1>
      <button onClick={() => router.push('/api/data')}>Get Data</button>
    </div>
  );
}

export async function getServerSideProps(context) {
  await corsMiddleware.handleRequest(context);

  // Your server-side logic goes here
