```javascript
function getEntriesByKey(obj, key) {
  const entries = [];

  Object.entries(obj).forEach(([nestedKey, value]) => {
    if (nestedKey === key) {
      entries.push(value);
    } else if (typeof value === 'object') {
      entries.push(...getEntriesByKey(value, key));
    }
  });

  return entries;
}
```

To use this function, you can pass in an object and a key as arguments:

