Here's a C function that converts an array of command-line arguments (`argv`) to a null-terminated string:

```c
#include <stdio.h>
#include <stdlib.h>

char *argv_to_str(int argc, char **argv) {
    size_t len = 0;
    for (int i = 0; i < argc; i++) {
        len += strlen(argv[i]) + 1; // Add one for the null terminator
    }
    char *str = malloc(len);
    if (str == NULL) {
        fprintf(stderr, "Error allocating memory\n");
        return NULL;
    }
    for (int i = 0; i < argc; i++) {
        strcat(str, argv[i]);
        strcat(str, " ");
    }
    str[len - 1] = '\0'; // Ensure the string is null-terminated
    return str;
}

int main(int argc, char **argv) {
    char *str = argv_to_str(argc, argv);
    if (str != NULL) {
        printf("Converted args to string: %s\n", str);
        free(str);
    }
    return 0;
}
```

