namespace HaikuGenerator
{
    class Program
    {
        static void Main(string[] args)
        {
            Haiku haiku = GenerateHaiku();
            string html = GetHtml(haiku);
            Console.WriteLine(html);
        }

        static Haiku GenerateHaiku()
        {
            List<string> lines = new List<string>
            {
                "A lone tree stands tall",
                "In the midst of a misty meadow",
                "Nature's beauty unfolds"
            };

            Random random = new Random();
            int index1 = random.Next(lines.Count);
            int index2 = random.Next(lines.Count);
            int index3 = random.Next(lines.Count);

            return new Haiku
            {
                Line1 = lines[index1],
                Line2 = lines[index2],
                Line3 = lines[index3]
            };
        }

        static string GetHtml(Haiku haiku)
        {
            return $"<div><p>{haiku.Line1}</p><p>{haiku.Line2}</p><p>{haiku.Line3}</p></div>";
        }
    }

    public class Haiku
    {
        public string Line1 { get; set; }
        public string Line2 { get; set; }
        public string Line3 { get; set; }
    }
}
