To create a Python function that meets all the requirements you've outlined, we can break it down into several parts. Here's a step-by-step approach:

1. Define a function to convert a number to its English word representation:

```python
def num_to_english(num):
    if num == 0:
        return "zero"
    elif num < 0:
        return "negative " + num_to_english(-num)
    else:
        words = []
        while num > 0:
            words.append(str(num % 10))
            num //= 10
        return " ".join(reversed(words))
```

2. Add support for handling scientific notation input:

```python
def num_to_english_scientific(num):
    if num == 0:
        return "zero"
    elif num < 0:
        return "negative " + num_to_english_scientific(-num)
    else:
        mantissa, exponent = num.as_tuple()
        words = []
        if mantissa != 0:
            words.append(num_to_english(mantissa))
        words.append("times ten to the power of")
        words.append(str(exponent))
        return " ".join(words)
