      p.position.some((coord, index) => {
        return Math.abs(coord - planet.position[index]) < minDistance;
      })
    );

    if (!tooClose) {
      planets.push(planet);
    } else {
      // Move one of the planets or generate a new one until the distance requirement is met
      const closestPlanet = planets.reduce((prev, curr) =>
        Math.min(prev.position.reduce((a, b) => Math.abs(a - b)), curr.position.reduce((a, b) => Math.abs(a - b)))
