To modify the given C++ code to work with Facebook's API, we need to replace the Twitter API calls with corresponding Facebook API calls. We also need to handle the differences in data structures returned by each API. Here's a modified version of the code that can efficiently retrieve and process data from Facebook's API:

```cpp
#include <iostream>
#include <curl/curl.h>
#include <json/json.h>

using namespace std;

string getFacebookData(string accessToken, string pageId) {
    CURL *curl;
    CURLcode res;
    string readBuffer;

    curl = curl_easy_init();
    if (curl) {
        string url = "https://graph.facebook.com/" + pageId + "/posts?access_token=" + accessToken;
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    return readBuffer;
}

