```javascript
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    const redisConfig = {
      host: 'localhost',
      port: 6379,
    };

    this.client = new Redis(redisConfig);

    this.client.on('error', (err) => {
      console.error('Error connecting to Redis:', err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      console.error('Error checking Redis connection:', err);
      return false;
    }
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error(`Error getting value from Redis: ${key}`, err);
      throw err;
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
    } catch (err) {
      console.error(`Error setting value in Redis: ${key}`, err);
      throw err;
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
    } catch (err) {
      console.error(`Error deleting value from Redis: ${key}`, err);
      throw err;
    }
  }
}

const redisClient = new RedisClient();

module.exports = redisClient;
```

This code defines the `RedisClient` class with its constructor, methods, and exports an instance of the class named `redisClient`. The class handles errors and provides methods for interacting with Redis.

